algorithms.pseudocode:
function GreedyMaximalPacking(F):
    P <- empty list        # chosen pairwise-disjoint members
    U <- empty set         # running union of chosen members
    for A in F:
        if A intersect U == empty:
            append A to P
            U <- U union A
    X <- U                 # hitting set = union of the packing
    return (P, X)

# Guarantees, when F is c-bounded with no s-packing:
#   (1) for every A in F: A intersect X is nonempty   (hitting set)
#   (2) |X| <= c * (|P|) <= c * (s - 1)               (size bound)

