function WallSeparator(traces, s):
    # traces: A-nail path traces, each of size <= 4
    (P, X) <- GreedyMaximalPacking(traces)
    if |P| >= s:
        return PACKING_HORN(P)      # s disjoint A-nail paths exist
    assert |X| <= 4*s - 4           # F(s); cover horn
    return COVER_HORN(X)

