function CleanSubwall(subwalls, X, endpoints):
    # subwalls: list of >= 8s+4 disjoint r-subwalls
    spoiled <- empty set
    for i, W in enumerate(subwalls):
        if vertices(W) intersect (X union endpoints) != empty:
            add i to spoiled
    for i, W in enumerate(subwalls):
        if i not in spoiled:
            return W        # clean r-subwall (>= 2s+8 remain)
    error 'unreachable: pigeonhole guarantees a clean subwall'

